CREATE TABLE `t_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `username` varchar(50) NOT NULL COMMENT '登录名',
  `password` varchar(100) NOT NULL COMMENT '密码（BCrypt 密文，禁止明文）',
  `nickname` varchar(50) DEFAULT NULL COMMENT '昵称',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1正常 0禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  KEY `idx_phone` (`phone`),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户表';

CREATE TABLE `t_address` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '地址ID',
  `user_id` bigint NOT NULL COMMENT '所属用户ID',
  `receiver_name` varchar(50) NOT NULL COMMENT '收货人姓名',
  `receiver_phone` varchar(20) NOT NULL COMMENT '收货人电话',
  `province` varchar(50) DEFAULT NULL COMMENT '省',
  `city` varchar(50) DEFAULT NULL COMMENT '市',
  `district` varchar(50) DEFAULT NULL COMMENT '区/县',
  `detail_address` varchar(255) NOT NULL COMMENT '详细地址',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '是否默认：1是 0否',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  KEY `idx_user_id` (`user_id`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='收货地址表';

CREATE TABLE `t_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `name` varchar(50) NOT NULL COMMENT '分类名称',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '父分类ID，0 表示一级分类',
  `icon` varchar(255) DEFAULT NULL COMMENT '分类图标',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序值，越小越靠前',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  KEY `idx_parent_id` (`parent_id`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品分类表';

CREATE TABLE `t_product` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '商品ID',
  `name` varchar(128) NOT NULL COMMENT '商品名称',
  `category_id` bigint DEFAULT NULL COMMENT '分类ID',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '售价',
  `stock` int NOT NULL DEFAULT '0' COMMENT '库存',
  `sales` int NOT NULL DEFAULT '0' COMMENT '下单件数：下单+、取消-（已创建且未取消）',
  `image` varchar(255) DEFAULT NULL COMMENT '商品主图',
  `description` text COMMENT '商品描述（可供 AI 引用）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：0下架 1上架',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  KEY `idx_category_id` (`category_id`),
  KEY `idx_name` (`name`),
  KEY `idx_status` (`status`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品表';

CREATE TABLE `t_product_attr` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '参数ID',
  `product_id` bigint NOT NULL COMMENT '所属商品ID',
  `attr_name` varchar(50) NOT NULL COMMENT '参数名，如 电池容量',
  `attr_value` varchar(255) NOT NULL COMMENT '参数值，如 5000mAh',
  `attr_group` varchar(50) DEFAULT NULL COMMENT '参数分组，如 屏幕/性能/续航',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序值，越小越靠前',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  KEY `idx_product_id` (`product_id`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品参数表';

CREATE TABLE `t_orders` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_no` varchar(32) NOT NULL COMMENT '业务订单号，对外暴露',
  `user_id` bigint NOT NULL COMMENT '下单用户ID',
  `total_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '订单总额',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0待付款 1已付款 2备货中 3已发货 4已签收 5已取消',
  `logistics_company` varchar(50) DEFAULT NULL COMMENT '物流公司',
  `tracking_no` varchar(64) DEFAULT NULL COMMENT '运单号',
  `receiver_name` varchar(50) NOT NULL COMMENT '收货人',
  `receiver_phone` varchar(20) NOT NULL COMMENT '联系电话',
  `receiver_address` varchar(255) NOT NULL COMMENT '收货地址（下单时快照）',
  `remark` varchar(255) DEFAULT NULL COMMENT '订单备注',
  `pay_time` datetime DEFAULT NULL COMMENT '支付时间',
  `ship_time` datetime DEFAULT NULL COMMENT '发货时间',
  `finish_time` datetime DEFAULT NULL COMMENT '完成（签收）时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  KEY `idx_create_time` (`create_time`),
  KEY `idx_status` (`status`),
  KEY `idx_user_id` (`user_id`),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='订单主表';

CREATE TABLE `t_order_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `order_id` bigint NOT NULL COMMENT '关联 t_orders.id',
  `order_no` varchar(32) NOT NULL COMMENT '订单号（冗余，便于查询）',
  `product_id` bigint NOT NULL COMMENT '商品ID',
  `product_name` varchar(128) NOT NULL COMMENT '商品名称（快照）',
  `product_image` varchar(255) DEFAULT NULL COMMENT '商品图片（快照）',
  `price` decimal(10,2) NOT NULL COMMENT '下单时单价（快照）',
  `quantity` int NOT NULL DEFAULT '1' COMMENT '购买数量',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删 1已删',
  `sku_id` bigint DEFAULT NULL,
  `sku_name` varchar(128) DEFAULT NULL,
  `sku_spec` varchar(1024) DEFAULT NULL,
  KEY `idx_item_sku` (`sku_id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_order_no` (`order_no`),
  KEY `idx_product_id` (`product_id`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='订单明细表';

CREATE TABLE `t_order_idempotency` (
  `user_id` bigint NOT NULL,
  `idempotency_key` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `hash_version` smallint NOT NULL,
  `request_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `order_no` varchar(32) NOT NULL,
  `result_status` int NOT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`,`idempotency_key`),
  UNIQUE KEY `uk_idempotency_order_no` (`order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='下单成功幂等回执';

CREATE TABLE `t_inventory_adjustment` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `business_no` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `sku_id` bigint NOT NULL,
  `event_type` varchar(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `quantity` int NOT NULL,
  `reason` varchar(200) NOT NULL,
  `actor_id` bigint DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `ck_adjustment_quantity` CHECK (((`quantity` <> 0) and ((`event_type` <> _utf8mb4'INBOUND') or (`quantity` > 0)))),
  CONSTRAINT `ck_adjustment_type` CHECK ((`event_type` in (_utf8mb4'INBOUND',_utf8mb4'ADJUSTMENT'))),
  KEY `idx_adjustment_sku` (`sku_id`,`id`),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_adjustment_business` (`business_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `t_inventory_ledger` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `sku_id` bigint NOT NULL,
  `event_type` varchar(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `business_no` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `quantity` int NOT NULL,
  `sales_quantity` int NOT NULL DEFAULT '0',
  `before_stock` int NOT NULL,
  `after_stock` int NOT NULL,
  `actor_id` bigint DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `restore_order_no` varchar(64) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS ((case when (`event_type` in (_ascii'CANCEL_RESTORE',_ascii'REFUND_RESTORE')) then `business_no` else NULL end)) STORED,
  CONSTRAINT `ck_inventory_balance` CHECK (((`before_stock` >= 0) and (`after_stock` >= 0) and ((cast(`before_stock` as signed) + `quantity`) = `after_stock`))),
  CONSTRAINT `ck_inventory_direction` CHECK ((((`event_type` = _utf8mb4'OPENING') and (`before_stock` = 0) and (`quantity` >= 0) and (`sales_quantity` >= 0)) or ((`event_type` = _utf8mb4'INBOUND') and (`quantity` > 0) and (`sales_quantity` = 0)) or ((`event_type` = _utf8mb4'ADJUSTMENT') and (`quantity` <> 0) and (`sales_quantity` = 0)) or ((`event_type` = _utf8mb4'ORDER_OCCUPY') and (`quantity` < 0) and (`sales_quantity` = -(`quantity`))) or ((`event_type` in (_utf8mb4'CANCEL_RESTORE',_utf8mb4'REFUND_RESTORE')) and (`quantity` > 0) and (`sales_quantity` = -(`quantity`))))),
  CONSTRAINT `ck_inventory_type` CHECK ((`event_type` in (_utf8mb4'OPENING',_utf8mb4'INBOUND',_utf8mb4'ADJUSTMENT',_utf8mb4'ORDER_OCCUPY',_utf8mb4'CANCEL_RESTORE',_utf8mb4'REFUND_RESTORE'))),
  KEY `idx_inventory_business` (`business_no`,`id`),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_inventory_event` (`sku_id`,`event_type`,`business_no`),
  UNIQUE KEY `uk_inventory_restore` (`sku_id`,`restore_order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `t_product_sku` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `product_id` bigint NOT NULL,
  `name` varchar(128) NOT NULL,
  `spec_json` varchar(1024) NOT NULL,
  `spec_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `price` decimal(10,2) NOT NULL,
  `stock` int NOT NULL DEFAULT '0',
  `sales` int NOT NULL DEFAULT '0',
  `image` varchar(255) DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `deleted` tinyint NOT NULL DEFAULT '0',
  `is_default` tinyint NOT NULL DEFAULT '0',
  `default_product_id` bigint GENERATED ALWAYS AS ((case when (`is_default` = 1) then `product_id` else NULL end)) STORED,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY `idx_sku_product` (`product_id`),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_default_sku` (`default_product_id`),
  UNIQUE KEY `uk_sku_specs` (`product_id`,`spec_hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='SKU唯一交易库存权威';

CREATE TABLE `t_catalog_migration` (
  `version` smallint NOT NULL,
  `completed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='分批默认SKU回填完成标记';

CREATE TABLE `t_admin_account` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `username` varchar(50) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `password` varchar(60) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `deleted` tinyint NOT NULL DEFAULT '0',
  `token_version` bigint NOT NULL DEFAULT '0',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT `ck_admin_deleted` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `ck_admin_status` CHECK ((`status` in (0,1))),
  CONSTRAINT `ck_admin_version` CHECK ((`token_version` >= 0)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_admin_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='独立后台身份与令牌撤销版本';

CREATE TABLE `t_admin_role` (
  `id` bigint NOT NULL,
  `code` varchar(50) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` varchar(100) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `t_admin_permission` (
  `code` varchar(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` varchar(100) NOT NULL,
  PRIMARY KEY (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `t_admin_role_permission` (
  `role_id` bigint NOT NULL,
  `permission_code` varchar(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  CONSTRAINT `fk_rp_permission` FOREIGN KEY (`permission_code`) REFERENCES `t_admin_permission` (`code`),
  CONSTRAINT `fk_rp_role` FOREIGN KEY (`role_id`) REFERENCES `t_admin_role` (`id`),
  KEY `fk_rp_permission` (`permission_code`),
  PRIMARY KEY (`role_id`,`permission_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `t_admin_account_role` (
  `admin_id` bigint NOT NULL,
  `role_id` bigint NOT NULL,
  CONSTRAINT `fk_ar_account` FOREIGN KEY (`admin_id`) REFERENCES `t_admin_account` (`id`),
  CONSTRAINT `fk_ar_role` FOREIGN KEY (`role_id`) REFERENCES `t_admin_role` (`id`),
  KEY `idx_ar_role` (`role_id`,`admin_id`),
  PRIMARY KEY (`admin_id`,`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `t_admin_audit` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `event_key` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `actor_type` varchar(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `actor_id` bigint DEFAULT NULL,
  `action` varchar(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `target_type` varchar(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `target_id` varchar(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `result` varchar(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'SUCCESS',
  `changes_json` json NOT NULL,
  `trace_id` char(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source` varchar(50) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `payload_sha256` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  CONSTRAINT `ck_audit_actor` CHECK ((((`actor_type` = _utf8mb4'ADMIN') and (`actor_id` is not null) and (`actor_id` > 0)) or ((`actor_type` = _utf8mb4'SYSTEM') and (`actor_id` is null)))),
  CONSTRAINT `ck_audit_result` CHECK ((`result` = _utf8mb4'SUCCESS')),
  KEY `idx_audit_actor` (`actor_id`,`created_at`,`id`),
  KEY `idx_audit_target` (`target_type`,`target_id`,`created_at`,`id`),
  KEY `idx_audit_time` (`created_at`,`id`),
  KEY `idx_audit_trace` (`trace_id`),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_audit_event` (`event_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='管理操作成功审计，时间为UTC，非不可篡改存储';

CREATE TABLE `t_cart_item` (
  `user_id` bigint NOT NULL,
  `sku_id` bigint NOT NULL,
  `quantity` int NOT NULL,
  `selected` tinyint NOT NULL DEFAULT '1',
  CONSTRAINT `chk_cart_quantity` CHECK ((`quantity` between 1 and 999)),
  CONSTRAINT `chk_cart_selected` CHECK ((`selected` in (0,1))),
  PRIMARY KEY (`user_id`,`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='买家购物车SKU清单';

CREATE TABLE `t_payment_order` (
  `order_id` bigint NOT NULL,
  `payment_no` char(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `channel` varchar(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `app_id` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `seller_id` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `status` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'PENDING',
  `trade_no` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `pay_time` datetime DEFAULT NULL,
  CONSTRAINT `fk_payment_order` FOREIGN KEY (`order_id`) REFERENCES `t_orders` (`id`),
  CONSTRAINT `chk_payment_amount` CHECK ((`total_amount` > 0)),
  CONSTRAINT `chk_payment_state` CHECK ((((`status` = _utf8mb4'PENDING') and (`trade_no` is null) and (`pay_time` is null)) or ((`status` = _utf8mb4'SUCCEEDED') and (`trade_no` is not null) and (`pay_time` is not null)))),
  PRIMARY KEY (`order_id`),
  UNIQUE KEY `uk_payment_no` (`payment_no`),
  UNIQUE KEY `uk_payment_trade` (`channel`,`trade_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='订单支付单';

CREATE TABLE `t_demo_payment_trade` (
  `payment_no` char(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_demo_trade_payment` FOREIGN KEY (`payment_no`) REFERENCES `t_payment_order` (`payment_no`),
  PRIMARY KEY (`payment_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='演示收银台的已付款回执';

